// The geometric engine: dye curves advected by an exactly area-preserving
// twist flow generated by swapping neighbouring rods.
//
// Slots q = 0..n-1 sit at (q, 0). A move ±i swaps slots i-1, i by rotating
// about c = (i - 1/2, 0). The flow at angle θ is the radial twist
//     (ρ, φ) ↦ (ρ, φ + s·θ·f(ρ)),   f = 1 (ρ ≤ R1), 0 (ρ ≥ R2), cosine ramp between,
// whose Jacobian has determinant exactly 1. Each frame positions are
// recomputed from the snapshot taken at the start of the move (no drift);
// new points are inserted as exact images of snapshot midpoints.

export const GEOM = Object.freeze({ rodR: 0.07, R1: 0.6, R2: 1.4, h: 0.03 });

// Orientation linking +i (positive generator) to a rotation sense. Fixed by
// tests/convention.test.mjs so geometric crossing counts dominate the exact
// Dynnikov minima: +1 = counter-clockwise (the opposite sense produces
// violations of geometric >= minimal within a few moves).
export const SIGMA_SENSE = 1;

export function profile(rho, R1 = GEOM.R1, R2 = GEOM.R2) {
  if (rho <= R1) return 1;
  if (rho >= R2) return 0;
  return 0.5 * (1 + Math.cos((Math.PI * (rho - R1)) / (R2 - R1)));
}

/** Twist map about (cx, 0) by signed angle a (radians, already including sense). */
export function twist(x, y, cx, a) {
  const dx = x - cx, dy = y;
  const rho = Math.hypot(dx, dy);
  const f = profile(rho);
  if (f === 0) return [x, y];
  const t = a * f;
  const c = Math.cos(t), s = Math.sin(t);
  return [cx + c * dx - s * dy, s * dx + c * dy];
}

const FIELDS = [['x', Float64Array], ['y', Float64Array], ['x0', Float64Array], ['y0', Float64Array],
  ['fz', Float64Array], ['age', Float32Array], ['tag', Int32Array]];

class Curve {
  constructor(xs, ys, hue) {
    const n = xs.length;
    this.alloc(Math.max(64, n * 2));
    this.x.set(xs); this.y.set(ys); this.x0.set(xs); this.y0.set(ys);
    for (let k = 0; k < n; k++) this.tag[k] = k;
    this.seedX = Float64Array.from(xs);
    this.seedY = Float64Array.from(ys);
    this.n = n;
    this.hue = hue;
    this.origCount = n;
    this.active = new Int32Array(0); // indices inside the current twist support
    this.nActive = 0;
  }

  // x, y: current; x0, y0: snapshot at move start; fz: twist profile f(ρ) of the
  // snapshot point (constant during a move); age: birth generation; tag: seed index or -1.
  alloc(cap) {
    this.cap = cap;
    for (const [k, T] of FIELDS) this[k] = new T(cap);
  }
}

export function ellipsePoints(cx, cy, rx, ry, h) {
  // Ramanujan perimeter → point count with spacing < h.
  const per = Math.PI * (3 * (rx + ry) - Math.sqrt((3 * rx + ry) * (rx + 3 * ry)));
  const m = Math.max(24, Math.ceil(per / (h * 0.7)));
  const xs = new Float64Array(m), ys = new Float64Array(m);
  for (let k = 0; k < m; k++) {
    const t = (2 * Math.PI * k) / m;
    xs[k] = cx + rx * Math.cos(t);
    ys[k] = cy + ry * Math.sin(t);
  }
  return [xs, ys];
}

export class Stirrer {
  /**
   * @param {number} n rods
   * @param {object} opts { seed: 'nested' | 'pair' | 'rings', maxPoints }
   */
  constructor(n, opts = {}) {
    if (n < 3 || n > 9) throw new Error('3..9 rods supported');
    this.n = n;
    this.maxPoints = opts.maxPoints ?? 600000;
    this.rodId = Array.from({ length: n }, (_, k) => k); // slot -> rod identity
    this.rodX = Float64Array.from({ length: n }, (_, k) => k);
    this.rodY = new Float64Array(n);
    this.move = null; // { g, i, cx, sense, theta }
    this.history = [];
    this.projections = 0;
    this.saturated = false;
    this.generation = 0;
    this.version = 0; // bumps whenever dye geometry changes (render cache key)
    this.seed(opts.seed ?? 'nested');
  }

  /** Dye patterns. 'nested' realises Dehornoy's lamination E = loops around {0,1}, {0,1,2}, ... */
  seed(kind) {
    const n = this.n, h = GEOM.h;
    this.seedKind = kind;
    this.curves = [];
    const groups = [];
    if (kind === 'nested') {
      for (let k = 2; k <= n - 1; k++) groups.push([0, k - 1]);
    } else if (kind === 'pair') {
      groups.push([0, 1]);
    } else if (kind === 'middle') {
      groups.push([1, n - 2]);
    } else throw new Error('unknown seed ' + kind);
    groups.forEach(([p, q], idx) => {
      const cx = (p + q) / 2;
      const rx = (q - p) / 2 + 0.25 + 0.03 * idx; // stays clear of the next gap line (≤ 0.43)
      const ry = 0.18 + 0.05 * idx;
      const [xs, ys] = ellipsePoints(cx, 0, rx, ry, h);
      this.curves.push(new Curve(xs, ys, idx / Math.max(1, groups.length)));
    });
    this.projections = 0;
    this.saturated = false;
    this.initialAreas = this.curves.map((c) => polygonArea(c));
    this.version++;
  }

  get pointCount() {
    let s = 0;
    for (const c of this.curves) s += c.n;
    return s;
  }

  get busy() {
    return this.move !== null;
  }

  beginMove(g) {
    if (this.move) throw new Error('move already in progress');
    const i = Math.abs(g);
    if (i < 1 || i > this.n - 1) throw new Error('bad generator ' + g);
    const cx = i - 0.5;
    for (const c of this.curves) {
      c.x0.set(c.x.subarray(0, c.n));
      c.y0.set(c.y.subarray(0, c.n));
      this.computeProfile(c, cx);
    }
    this.move = { g, i, cx, sense: Math.sign(g) * SIGMA_SENSE, theta: 0 };
    this.generation++;
  }

  /** Cache f(ρ) for every snapshot point and collect the indices with f > 0. */
  computeProfile(c, cx) {
    const R2 = GEOM.R2;
    if (c.active.length < c.n) c.active = new Int32Array(c.cap);
    let m = 0;
    for (let k = 0; k < c.n; k++) {
      const dx = c.x0[k] - cx, dy = c.y0[k];
      let f = 0;
      if (dx < R2 && dx > -R2 && dy < R2 && dy > -R2) f = profile(Math.sqrt(dx * dx + dy * dy));
      c.fz[k] = f;
      if (f > 0) c.active[m++] = k;
    }
    c.nActive = m;
  }

  /** Set the move's progress angle θ ∈ [0, π]; returns number of points inserted. */
  setTheta(theta) {
    const m = this.move;
    m.theta = theta;
    this.version++;
    const a = m.sense * theta;
    const cx = m.cx;
    for (const c of this.curves) {
      const { x, y, x0, y0, fz, active } = c;
      for (let j = 0; j < c.nActive; j++) {
        const k = active[j];
        const t = a * fz[k];
        const co = Math.cos(t), si = Math.sin(t);
        const dx = x0[k] - cx, dy = y0[k];
        x[k] = cx + co * dx - si * dy;
        y[k] = si * dx + co * dy;
      }
    }
    // Rods in the twist core rotate rigidly.
    const p = m.i - 1, q = m.i;
    const co = Math.cos(a), si = Math.sin(a);
    this.rodX[p] = cx + co * -0.5; this.rodY[p] = si * -0.5;
    this.rodX[q] = cx + co * 0.5; this.rodY[q] = si * 0.5;
    return this.refine();
  }

  endMove() {
    const m = this.move;
    this.setTheta(Math.PI);
    // Snap rods exactly back onto slots and swap identities.
    const p = m.i - 1, q = m.i;
    this.rodX[p] = p; this.rodY[p] = 0;
    this.rodX[q] = q; this.rodY[q] = 0;
    const t = this.rodId[p]; this.rodId[p] = this.rodId[q]; this.rodId[q] = t;
    this.history.push(m.g);
    this.move = null;
  }

  /** Run one whole move instantly (used by tests and fast-forward). */
  applyMove(g, steps = 24) {
    this.beginMove(g);
    for (let s = 1; s < steps; s++) this.setTheta((Math.PI * s) / steps);
    this.endMove();
  }

  applyWord(w, steps) {
    for (const g of w) this.applyMove(g, steps);
  }

  /**
   * Subdivide any segment longer than h, inserting the exact image of the
   * snapshot midpoint. Output goes to reusable typed buffers (no per-frame
   * garbage); only curves that actually need refinement are rebuilt.
   */
  refine() {
    const h2 = GEOM.h * GEOM.h;
    const m = this.move;
    let inserted = 0;
    for (const c of this.curves) {
      const N = c.n;
      const { x, y } = c;
      let first = -1;
      for (let k = 0; k < N; k++) {
        const j = k + 1 === N ? 0 : k + 1;
        const dx = x[j] - x[k], dy = y[j] - y[k];
        if (dx * dx + dy * dy > h2) { first = k; break; }
      }
      if (first < 0) continue;
      if (this.pointCount > this.maxPoints) { this.saturated = true; continue; }
      const out = this.scratch(Math.ceil(c.n * 1.5) + 1024);
      let M = 0;
      const a = m ? m.sense * m.theta : 0;
      const cx = m ? m.cx : 0;
      const push = (px, py, px0, py0, f, ag, tg) => {
        if (M >= out.cap) out.grow(M * 2 + 64, M);
        out.x[M] = px; out.y[M] = py; out.x0[M] = px0; out.y0[M] = py0; out.fz[M] = f; out.age[M] = ag; out.tag[M] = tg;
        M++;
      };
      const self = this;
      const R2 = GEOM.R2;
      const emit = (px0, py0, pxx, pyy, qx0, qy0, qxx, qyy, depth) => {
        const dx = qxx - pxx, dy = qyy - pyy;
        if (dx * dx + dy * dy <= h2 || depth > 18) return;
        let mx0 = 0.5 * (px0 + qx0), my0 = 0.5 * (py0 + qy0);
        [mx0, my0] = self.pushOutOfRods(mx0, my0);
        let f = 0, mx = mx0, my = my0;
        if (m) {
          const ddx = mx0 - cx, ddy = my0;
          if (ddx < R2 && ddx > -R2 && ddy < R2 && ddy > -R2) f = profile(Math.sqrt(ddx * ddx + ddy * ddy));
          if (f > 0) {
            const t = a * f, co = Math.cos(t), si = Math.sin(t);
            mx = cx + co * ddx - si * ddy;
            my = si * ddx + co * ddy;
          }
        }
        emit(px0, py0, pxx, pyy, mx0, my0, mx, my, depth + 1);
        push(mx, my, mx0, my0, f, self.generation, -1);
        inserted++;
        emit(mx0, my0, mx, my, qx0, qy0, qxx, qyy, depth + 1);
      };
      // Unchanged runs are block-copied (memcpy); only long segments do work.
      const copyRun = (from, to) => {
        const len = to - from;
        if (len <= 0) return;
        if (M + len > out.cap) out.grow(Math.max(out.cap * 2, M + len + 64), M);
        if (len < 64) {
          // Short runs: a scalar loop beats creating 7 subarray views.
          const ox = out.x, oy = out.y, ox0 = out.x0, oy0 = out.y0, of = out.fz, oa = out.age, ot = out.tag;
          const cx_ = c.x, cy_ = c.y, cx0 = c.x0, cy0 = c.y0, cf = c.fz, ca = c.age, ct = c.tag;
          for (let k = from, d = M; k < to; k++, d++) {
            ox[d] = cx_[k]; oy[d] = cy_[k]; ox0[d] = cx0[k]; oy0[d] = cy0[k]; of[d] = cf[k]; oa[d] = ca[k]; ot[d] = ct[k];
          }
        } else {
          for (const [key] of FIELDS) out[key].set(c[key].subarray(from, to), M);
        }
        M += len;
      };
      let runStart = 0;
      for (let k = first; k < N; k++) {
        const j = k + 1 === N ? 0 : k + 1;
        const dx = x[j] - x[k], dy = y[j] - y[k];
        if (dx * dx + dy * dy <= h2) continue;
        copyRun(runStart, k + 1);
        runStart = k + 1;
        emit(c.x0[k], c.y0[k], x[k], y[k], c.x0[j], c.y0[j], x[j], y[j], 0);
      }
      copyRun(runStart, N);
      // Swap buffers: the curve adopts the scratch arrays, scratch keeps the old ones.
      for (const [key] of FIELDS) { const t = c[key]; c[key] = out[key]; out[key] = t; }
      const capC = c.cap; c.cap = out.cap; out.cap = capC;
      c.n = M;
      // Rebuild the active list (indices shifted).
      if (c.active.length < c.cap) c.active = new Int32Array(c.cap);
      let na = 0;
      for (let k = 0; k < M; k++) if (c.fz[k] > 0) c.active[na++] = k;
      c.nActive = na;
    }
    return inserted;
  }

  /** A reusable scratch buffer set shared by all curves. */
  scratch(minCap) {
    if (!this._scratch) {
      const sc = { cap: 0 };
      // grow(cap, keep): reallocate, preserving only the first `keep` filled entries.
      sc.grow = (cap, keep = 0) => {
        sc.cap = cap;
        for (const [k, T] of FIELDS) {
          const arr = new T(cap);
          if (keep > 0) arr.set(sc[k].subarray(0, keep));
          sc[k] = arr;
        }
      };
      this._scratch = sc;
    }
    if (this._scratch.cap < minCap) this._scratch.grow(minCap);
    return this._scratch;
  }

  /**
   * Snapshot-space rod positions are the slots (moves start from rest). A
   * snapshot midpoint of a chord that clips a rod is pushed radially to the
   * rod surface: a tiny isotopy that never crosses another obstacle.
   */
  pushOutOfRods(x, y) {
    const r = GEOM.rodR * 1.0001;
    const q = Math.round(x);
    if (q >= 0 && q < this.n) {
      const dx = x - q, dy = y;
      const d = Math.hypot(dx, dy);
      if (d < r) {
        this.projections++;
        if (d < 1e-12) return [q, r];
        return [q + (dx / d) * r, (dy / d) * r];
      }
    }
    return [x, y];
  }

  /** Geometric crossing counts with the Dynnikov arc system. */
  crossings() {
    const n = this.n;
    const nu = new Array(n - 1).fill(0);
    const up = new Array(n - 2).fill(0), down = new Array(n - 2).fill(0);
    for (const c of this.curves) {
      const { x, y } = c;
      const N = c.n;
      for (let k = 0; k < N; k++) {
        const j = k + 1 === N ? 0 : k + 1;
        const x1 = x[k], x2 = x[j];
        let lo = x1 < x2 ? x1 : x2, hi = x1 < x2 ? x2 : x1;
        // gap lines at g + 0.5 and puncture columns at q, i.e. multiples of 0.5
        let s = Math.ceil(lo * 2 - 1e-15);
        for (; s / 2 <= hi; s++) {
          const xc = s / 2;
          // half-open rule: crossing iff endpoints on opposite sides of xc (>= convention)
          if ((x1 >= xc) === (x2 >= xc)) continue;
          if (s % 2 !== 0) {
            const g = (s - 1) / 2;
            if (g >= 0 && g < n - 1) nu[g]++;
          } else {
            const q = s / 2;
            if (q >= 1 && q <= n - 2) {
              const t = (xc - x1) / (x2 - x1);
              const yc = y[k] + t * (y[j] - y[k]);
              if (yc > 0) up[q - 1]++; else down[q - 1]++;
            }
          }
        }
      }
    }
    return { nu, up, down };
  }

  length() {
    let s = 0;
    for (const c of this.curves) {
      for (let k = 0; k < c.n; k++) {
        const j = k + 1 === c.n ? 0 : k + 1;
        const dx = c.x[j] - c.x[k], dy = c.y[j] - c.y[k];
        s += Math.sqrt(dx * dx + dy * dy);
      }
    }
    return s;
  }

  /** Smallest distance from any dye point to any rod centre (must stay ≥ rodR). */
  minRodClearance() {
    let best = Infinity;
    for (const c of this.curves) {
      for (let k = 0; k < c.n; k++) {
        for (let q = 0; q < this.n; q++) {
          const dx = c.x[k] - this.rodX[q], dy = c.y[k] - this.rodY[q];
          if (dx > 0.5 || dx < -0.5) continue;
          const d = Math.sqrt(dx * dx + dy * dy);
          if (d < best) best = d;
        }
      }
    }
    return best;
  }

  /**
   * Max displacement of the original seed points from where they started.
   * Exactly 0 (up to rounding) whenever the move history freely reduces to e.
   */
  reversibilityError() {
    let e = 0;
    for (const c of this.curves) {
      for (let k = 0; k < c.n; k++) {
        const t = c.tag[k];
        if (t < 0) continue;
        const d = Math.hypot(c.x[k] - c.seedX[t], c.y[k] - c.seedY[t]);
        if (d > e) e = d;
      }
    }
    return e;
  }

  /** Per-curve lengths. */
  curveLengths() {
    return this.curves.map((c) => {
      let s = 0;
      for (let k = 0; k < c.n; k++) {
        const j = k + 1 === c.n ? 0 : k + 1;
        const dx = c.x[j] - c.x[k], dy = c.y[j] - c.y[k];
        s += Math.sqrt(dx * dx + dy * dy);
      }
      return s;
    });
  }

  areas() {
    return this.curves.map((c) => polygonArea(c));
  }

  /** FNV-1a hash over the exact bit patterns of all positions. */
  hash() {
    let h = 0x811c9dc5 >>> 0;
    for (const c of this.curves) {
      const bytes = new Uint8Array(c.x.buffer, 0, c.n * 8);
      const bytes2 = new Uint8Array(c.y.buffer, 0, c.n * 8);
      for (const b of [bytes, bytes2])
        for (let k = 0; k < b.length; k++) { h ^= b[k]; h = Math.imul(h, 0x01000193) >>> 0; }
    }
    return h.toString(16).padStart(8, '0');
  }
}

export function polygonArea(c) {
  let s = 0;
  const { x, y } = c;
  for (let k = 0; k < c.n; k++) {
    const j = k + 1 === c.n ? 0 : k + 1;
    s += x[k] * y[j] - x[j] * y[k];
  }
  return 0.5 * s;
}
